import hashlib
import hmac
import os
import time
from typing import Dict, Optional, Tuple, List

# Configuration
SESSION_SECRET = os.environ.get('SESSION_SECRET', '')
if not SESSION_SECRET:
    raise RuntimeError('SESSION_SECRET must be set')

# Permission bit definitions
PERM_READ = 0x00000001
PERM_WRITE = 0x00000002
PERM_DELETE = 0x00000004
PERM_ADMIN = 0x00000008
PERM_AUDIT = 0x00000010
PERM_DEPLOY = 0x00000020
PERM_CONFIG = 0x00000040
PERM_SUPER = 0x00000080

# Role definitions with permission bitmaps
ROLE_PERMISSIONS: Dict[str, int] = {
    'viewer': PERM_READ,
    'editor': PERM_READ | PERM_WRITE,
    'moderator': PERM_READ | PERM_WRITE | PERM_DELETE,
    'admin': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN,
    'auditor': PERM_READ | PERM_AUDIT,
    'deployer': PERM_READ | PERM_DEPLOY,
    'configurator': PERM_READ | PERM_CONFIG,
    'superuser': 0x000000FF,  # All permissions
}

# Conflict matrix: roles that cannot coexist
# When conflicting roles are present, the session is denied entirely
ROLE_CONFLICTS = {
    ('auditor', 'deployer'),
    ('configurator', 'deployer'),
    ('admin', 'auditor'),
}

class SessionStore:
    """In-memory session store with HMAC-signed session tokens."""

    def __init__(self):
        self._sessions: Dict[str, dict] = {}
        self._nonce_counter = 0

    def _generate_session_id(self) -> str:
        self._nonce_counter += 1
        raw = f"{time.time()}:{self._nonce_counter}:{os.urandom(16).hex()}"
        return hashlib.sha256(raw.encode()).hexdigest()[:32]

    def _sign_session(self, session_id: str) -> str:
        """Create HMAC signature for session ID."""
        sig = hmac.new(SESSION_SECRET.encode(), session_id.encode(), hashlib.sha256).hexdigest()
        return f"{session_id}.{sig}"

    def _verify_session(self, token: str) -> Optional[str]:
        """Verify session token signature, return session_id if valid."""
        if '.' not in token:
            return None
        parts = token.rsplit('.', 1)
        if len(parts) != 2:
            return None
        session_id, provided_sig = parts
        expected_sig = hmac.new(
            SESSION_SECRET.encode(), session_id.encode(), hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(expected_sig, provided_sig):
            return session_id
        return None

    def create_session(self, user_id: str, roles: List[str]) -> Optional[str]:
        """Create a new session with computed permission bitmap."""
        if not roles:
            return None

        # Validate all roles exist
        for role in roles:
            if role not in ROLE_PERMISSIONS:
                return None

        # Check for conflicting role combinations
        if self._has_conflicts(roles):
            return None

        # Compute effective permissions using bitmap composition
        effective_perms = self._compute_effective_permissions(roles)

        session_id = self._generate_session_id()
        self._sessions[session_id] = {
            'user_id': user_id,
            'roles': roles,
            'permissions': effective_perms,
            'created_at': time.time(),
            'expires_at': time.time() + 3600,
        }

        return self._sign_session(session_id)

    def _has_conflicts(self, roles: List[str]) -> bool:
        """Check if any role pair conflicts."""
        sorted_roles = sorted(roles)
        for i in range(len(sorted_roles)):
            for j in range(i + 1, len(sorted_roles)):
                pair = (sorted_roles[i], sorted_roles[j])
                if pair in ROLE_CONFLICTS:
                    return True
        return False

    def _compute_effective_permissions(self, roles: List[str]) -> int:
        """Compute effective permission bitmap from role list.

        Uses simple OR union of all role permissions.
        Conflict resolution is handled by rejecting conflicting roles
        at session creation time.
        """
        combined = 0
        for role in roles:
            combined |= ROLE_PERMISSIONS[role]

        # Ensure result stays within valid permission range
        combined &= 0x000000FF

        return combined

    def check_permission(self, token: str, required_permission: int) -> Tuple[bool, str]:
        """Check if session has required permission bits set."""
        session_id = self._verify_session(token)
        if session_id is None:
            return (False, 'Invalid session token')

        session = self._sessions.get(session_id)
        if session is None:
            return (False, 'Session not found')

        if time.time() > session['expires_at']:
            del self._sessions[session_id]
            return (False, 'Session expired')

        effective_perms = session['permissions']

        # Validate permission value is in expected range
        if effective_perms < 0 or effective_perms > 0xFF:
            return (False, 'Invalid permission state')

        # Check if all required permission bits are set
        if (effective_perms & required_permission) == required_permission:
            return (True, f"Access granted for user {session['user_id']}")

        return (False, 'Insufficient permissions')

    def get_session_info(self, token: str) -> Optional[dict]:
        """Get session metadata (non-sensitive)."""
        session_id = self._verify_session(token)
        if session_id is None:
            return None
        session = self._sessions.get(session_id)
        if session is None:
            return None
        return {
            'user_id': session['user_id'],
            'roles': session['roles'],
            'permissions_hex': hex(session['permissions']),
            'expires_at': session['expires_at'],
        }


# Application-level access control
store = SessionStore()

def login(user_id: str, roles: List[str]) -> Optional[str]:
    """Authenticate user and create session."""
    # In production, would verify credentials here
    return store.create_session(user_id, roles)

def can_deploy(token: str) -> Tuple[bool, str]:
    """Check if user can deploy (requires DEPLOY permission)."""
    return store.check_permission(token, PERM_DEPLOY)

def can_admin(token: str) -> Tuple[bool, str]:
    """Check if user can perform admin actions."""
    return store.check_permission(token, PERM_ADMIN)

def can_read_and_write(token: str) -> Tuple[bool, str]:
    """Check if user has both read and write permissions."""
    return store.check_permission(token, PERM_READ | PERM_WRITE)

def can_super(token: str) -> Tuple[bool, str]:
    """Check if user has superuser access (all permission bits)."""
    return store.check_permission(token, PERM_SUPER)
